// The two stylesheets are linked with media="print" (not render-blocking: the splash and the SEO text are styled by the inline <style>) and
// switched on here once each has loaded, before the app is imported, so the map controls are styled when React mounts.  A stylesheet that fails
// or takes longer than 3 s never holds the app back.  `gt-css` on <html> says "the deferred stylesheets are applied (or given up on)": until then the
// Extra Features overlay stays hidden (see the inline rule), so it can never be revealed unstyled.
function css(done) {
  var ls = document.querySelectorAll('link[data-gt-defer]'), left = ls.length, over = false;
  function fin() { if (!over) { over = true; done(); } }
  function one() { if (--left <= 0) fin(); }
  if (!left) return fin();
  setTimeout(fin, 3000);
  for (var i = 0; i < ls.length; i++) (function (l) {
    function ok() { l.media = 'all'; one(); }
    if (l.sheet) ok(); else { l.addEventListener('load', ok); l.addEventListener('error', one); }
  })(ls[i]);
}
function start() { if (started) return; started = true; css(function () { document.documentElement.classList.add('gt-css'); setTimeout(function () { import(ENTRY).catch(fail); }, 0); }); }

button { font-family: inherit; }
/* First-paint rules that live in the app stylesheet (the AX shim) but style the static shell.  The app stylesheet is applied after the first paint
   (media="print", switched on by the loader), so the skip links, the screen-reader heading and the splash caption must not wait for it.
   Kept equal to the rules in the app stylesheet by tests/t0/perf-fixes.spec.mjs (PF-04). */
.gt-sr-only{position:absolute!important;width:1px;height:1px;margin:-1px;padding:0;border:0;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap}
.gt-skip{position:fixed;left:8px;top:-120px;z-index:1000001;padding:10px 16px;background:#0a0a14;color:#f4f0e4;border:2px solid #fff;border-radius:6px;font:600 14px/1.2 system-ui,sans-serif;text-decoration:none}
.gt-skip:focus{top:8px}
#boot-splash .boot-caption{color:#9a9aab!important}
@media (pointer:coarse){#root a[href]{min-width:44px;min-height:44px}}
html:not(.gt-css) #extra-features{visibility:hidden!important}
